<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\ClientIdentity\Infrastructure\Driven;

use Override;
use Throwable;
use Civi\Lughauth\Features\Access\ClientIdentity\Infrastructure\Connector\Pdo\ClientIdentityPdoConnector;
use Civi\Lughauth\Features\Access\ClientIdentity\Domain\Gateway\ClientIdentityReadGateway;
use Civi\Lughauth\Features\Access\ClientIdentity\Domain\Gateway\ClientIdentitySlide;
use Civi\Lughauth\Features\Access\ClientIdentity\Domain\Gateway\ClientIdentityFilter;
use Civi\Lughauth\Features\Access\ClientIdentity\Domain\Gateway\ClientIdentityCursor;
use Civi\Lughauth\Features\Access\ClientIdentity\Domain\ClientIdentityRef;
use Civi\Lughauth\Features\Access\ClientIdentity\Domain\ClientIdentity;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class ClientIdentityReadRepositoryAdapter implements ClientIdentityReadGateway
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly ClientIdentityPdoConnector $conn,
    ) {
    }
    #[Override]
    public function resolve(ClientIdentityRef $ref): ?ClientIdentity
    {
        if ($ref instanceof ClientIdentity) {
            return $ref;
        } elseif (!$ref->_private_resolve) {
            $ref->_private_resolve = $this->conn->retrieve(new ClientIdentityFilter(uids: [ $ref->uid() ]));
        }
        return $ref->_private_resolve;
    }
    #[Override]
    public function list(?ClientIdentityFilter $filter = null, ?ClientIdentityCursor $cursor = null): ClientIdentitySlide
    {
        $this->logDebug("List for Client identity on adapter ");
        $span = $this->startSpan("List for Client identity on adapter");
        try {
            $values = $this->conn->list($filter, $cursor);
            $last = end($values);
            return new ClientIdentitySlide(function (ClientIdentityFilter $slide, ?ClientIdentityCursor $next) use ($filter) {
                return $this->list($filter, $next);
            }, new ClientIdentityCursor($cursor?->limit() ?? 100, $last->uid ?? null), $values);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function retrieve(ClientIdentityFilter $filter): ?ClientIdentity
    {
        $this->logDebug("Retrieve for Client identity on adapter ");
        $span = $this->startSpan("Retrieve for Client identity on adapter");
        try {
            return $this->conn->retrieve($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function exists(ClientIdentityFilter $filter): bool
    {
        $this->logDebug("Exists for Client identity on adapter ");
        $span = $this->startSpan("Exists for Client identity on adapter");
        try {
            return $this->conn->exists($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function count(?ClientIdentityFilter $filter = null): int
    {
        $this->logDebug("Count for Client identity on adapter ");
        $span = $this->startSpan("Count for Client identity on adapter");
        try {
            return $this->conn->count($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function findOneByUid(string $uid): ?ClientIdentity
    {
        $this->logDebug("Find on by uid for Client identity on adapter");
        $span = $this->startSpan("Find on by uid for Client identity on adapter");
        try {
            return $this->conn->retrieve(new ClientIdentityFilter(uids: [$uid]));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
